/* eslint-disable solid/no-innerhtml */

import { createMemo, createSignal, For, ParentProps, Show } from "solid-js";
import { render } from "solid-js/web";

import { Button } from "#core/ui-next/components/button.jsx";
import { Header } from "#core/ui-next/components/header.jsx";
import { Panel } from "#core/ui-next/components/panel.jsx";
import { RadioButton } from "#core/ui-next/components/radio-button.jsx";
import { SandboxBox } from "#core/ui-next/sandbox/sandbox-box.jsx";

enum FontSize {
	XXS,
	XS,
	S,
	M,
	L,
	XL,
	XXL,
}

enum Font {
	Body,
	Title,
}

function ScratchPad() {
	const [text, setText] = createSignal("");
	const [textSize, setTextSize] = createSignal(FontSize.M);
	const [font, setFont] = createSignal(Font.Body);
	const [width, setWidth] = createSignal(600);
	const [lookupId, setLookupId] = createSignal("LOC_BUILDING_ACADEMY_DESCRIPTION");
	const [colorizeIconBackgrounds, setColorizeIconBackgrounds] = createSignal(false);
	const [showDebugHTML, setShowDebugHTML] = createSignal(false);

	const stylizedText = createMemo(() => Locale.stylize(text()));

	const handleLookup = async () => {
		const key = lookupId();
		setText(Locale.compose(key));
	};

	const handleTextChange = (text: string) => {
		setText(text);
	};

	const increaseWidth = () => {
		setWidth(width() + 10);
	};

	const decreaseWidth = () => {
		const w = width();
		if (w - 10 > 0) {
			setWidth(w - 10);
		}
	};

	const toggleColorizeIconBackgrounds = () => {
		setColorizeIconBackgrounds(!colorizeIconBackgrounds());
	};

	const toggleShowDebugHTML = () => {
		setShowDebugHTML(!showDebugHTML());
	};

	const getTextSizeSuffix = () => {
		switch (textSize()) {
			case FontSize.XXS:
				return "2xs";
			case FontSize.XS:
				return "xs";
			case FontSize.S:
				return "sm";
				break;
			case FontSize.L:
				return "lg";
			case FontSize.XL:
				return "xl";
			case FontSize.XXL:
				return "2xl";
			case FontSize.M:
			default:
				return "base";
		}
	};

	const getFontName = () => {
		switch (font()) {
			case Font.Title:
				return "title";
			case Font.Body:
			default:
				return "body";
		}
	};

	const getTextCSS = () => {
		const suffix = getTextSizeSuffix();
		const font = getFontName();
		return `font-${font}-${suffix}`;
	};

	const FontsWithName = [
		{ font: Font.Body, name: "Body" },
		{ font: Font.Title, name: "Title" },
	];

	const SizesWithName = [
		{ size: FontSize.XXS, name: "XXS" },
		{ size: FontSize.XS, name: "XS" },
		{ size: FontSize.S, name: "S" },
		{ size: FontSize.M, name: "M" },
		{ size: FontSize.L, name: "L" },
		{ size: FontSize.XL, name: "XL" },
		{ size: FontSize.XXL, name: "XXL" },
	];

	function WhenFinished(props: ParentProps) {
		const [resume, setResume] = createSignal(false);
		Loading.whenFinished.then(() => {
			setResume(true);
		});

		return (
			<Show
				when={resume()}
				fallback={<div class="flex flex-auto justify-center items-center font-body-2xl">Loading...</div>}
			>
				{props.children}
			</Show>
		);
	}

	return (
		<>
			<Header class="font-title text-2xl">Text Scratchpad!</Header>
			<p class="font-title ml-4 mb-4">Enter or lookup text to preview the formatted result.</p>
			<WhenFinished>
				<div class="w-full flex flex-row justify-center">
					<div class="flex flex-1 flex-col p-4">
						<div class="flex flex-row">
							<textarea
								value={lookupId()}
								onChange={(e) => setLookupId(e.target.value)}
								class="text-base flex flex-auto mb-4"
							>
								Enter ID to lookup text.
							</textarea>
							<Button
								onClick={handleLookup}
								class="mb-4 ml-4"
							>
								Lookup Text
							</Button>
						</div>

						<textarea
							value={text()}
							onInput={(e) => handleTextChange(e.target.value)}
							placeholder="Enter custom text or retrieved text will be displayed here"
							class="text-base w-full h-64 p-2 flex-auto"
						/>
					</div>
					<div class="flex flex-2 flex-col p-4">
						<div>
							<div class="flex flex-row items-center">
								Font:
								<div class="flex flex-row ml-2">
									<For each={FontsWithName}>
										{(item, index) => (
											<>
												<div class="flex flex-row items-center">
													<RadioButton
														isChecked={font() == item.font}
														onActivate={() => setFont(item.font)}
													/>
													{item.name}
													<Show when={index() != FontsWithName.length - 1}>,</Show>
												</div>
											</>
										)}
									</For>
								</div>
							</div>
							<div class="flex flex-row items-center">
								Size:
								<div class="flex flex-row ml-2">
									<For each={SizesWithName}>
										{(item, index) => (
											<>
												<div class="flex flex-row items-center">
													<RadioButton
														isChecked={textSize() == item.size}
														onActivate={() => setTextSize(item.size)}
													/>
													{item.name}
													<Show when={index() != SizesWithName.length - 1}>,</Show>
												</div>
											</>
										)}
									</For>
								</div>
							</div>
							<div class="flex flex-row items-center">
								Colorize Icon Backgrounds:
								<RadioButton
									isChecked={colorizeIconBackgrounds()}
									onActivate={toggleColorizeIconBackgrounds}
								/>
							</div>
							<div class="flex flex-row items-center">
								Show HTML:
								<RadioButton
									isChecked={showDebugHTML()}
									onActivate={toggleShowDebugHTML}
								/>
							</div>
						</div>
						<Show
							when={!showDebugHTML()}
							fallback={
								<SandboxBox
									class="flex-auto"
									style={{ width: `${width()}px` }}
								>
									<div class={`w-full h-64 p-2 ${getTextCSS()}`}>{stylizedText()}</div>
								</SandboxBox>
							}
						>
							<SandboxBox
								class={`flex-auto ${colorizeIconBackgrounds() ? "colorize-icons" : ""}`}
								style={{ width: `${width()}px` }}
							>
								<div
									innerHTML={stylizedText()}
									class={`w-full h-64 p-2 ${getTextCSS()}`}
								/>
							</SandboxBox>
						</Show>

						<div class="flex flex-row text-base items-center font-base ">
							Adjust Width:
							<Button
								onClick={decreaseWidth}
								class="ml-4"
							>
								-
							</Button>
							<Button
								onClick={increaseWidth}
								class="ml-4"
							>
								+
							</Button>
						</div>
					</div>
				</div>
			</WhenFinished>
		</>
	);
}

engine.whenReady.then(() => {
	render(() => {
		return (
			<Panel
				id="scratchpad"
				name="Text Scratchpad"
				class="w-full h-full flex flex-col"
			>
				<ScratchPad />
			</Panel>
		);
	}, document.getElementById("root")!);
});
